-- composition of rule kernels common_subexpressions x reorder_filter (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT (-1) AS c0 FROM (tl AS a1 JOIN (t1 POSITIONAL JOIN t3) ON ((a1.c0 = t3.c0) AND t3.c1)) WHERE GREATEST (((t1.c2 = '{"k": -1, "a": [1, 2, 3]}'::jsonb) OR TRUE), t3.c1)) AS ka UNION ALL SELECT 2 AS k FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT LIST_HAS_ALL (ARRAY[a1.c0], CASE WHEN TRUE THEN ARRAY_REVERSE (ARRAY[a1.c0]) ELSE ARRAY[1, 2, 3] END) AS c0, 'ß'::text AS c1 FROM t1 AS a1) AS kb) AS u;
